import { AbilityConstant, UIAbility, Want, abilityAccessCtrl, Permissions, common } from '@kit.AbilityKit';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { window } from '@kit.ArkUI';

const DOMAIN: number = 0x0000;
const TAG: string = 'EntryAbility';

export default class EntryAbility extends UIAbility {
  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {
    hilog.info(DOMAIN, TAG, 'onCreate');
    const atManager = abilityAccessCtrl.createAtManager();
    const perms: Permissions[] = [
      'ohos.permission.APPROXIMATELY_LOCATION',
      'ohos.permission.LOCATION',
      'ohos.permission.WRITE_IMAGEVIDEO',
      'ohos.permission.READ_IMAGEVIDEO'
    ];
    try {
      atManager.requestPermissionsFromUser(this.context, perms)
        .then((data) => {
          hilog.info(DOMAIN, TAG, 'perm result: %{public}s', JSON.stringify(data.authResults));
        })
        .catch((err: Error) => {
          hilog.error(DOMAIN, TAG, 'perm error: %{public}s', err.message);
        });
    } catch (err) {
      hilog.error(DOMAIN, TAG, 'perm catch: %{public}s', JSON.stringify(err));
    }
  }

  onWindowStageCreate(windowStage: window.WindowStage): void {
    windowStage.loadContent('pages/Index', (err) => {
      if (err.code) {
        hilog.error(DOMAIN, TAG, 'loadContent failed %{public}d', err.code);
        return;
      }
      hilog.info(DOMAIN, TAG, 'loadContent ok');
    });
  }

  onForeground(): void {}
  onBackground(): void {}
  onDestroy(): void {
    hilog.info(DOMAIN, TAG, 'onDestroy');
  }
}

import { webview } from '@kit.ArkWeb';
import { promptAction, common } from '@kit.ArkUI';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { request } from '@kit.BasicServicesKit';
import { photoAccessHelper } from '@kit.MediaLibraryKit';
import { fileIo } from '@kit.CoreFileKit';

const TARGET_URL: string = 'https://szfmh.szzfcjj.cn:8999';
const DOMAIN: number = 0x0000;
const TAG: string = 'Index';

@Entry
@Component
struct Index {
  controller: webview.WebviewController = new webview.WebviewController();
  @State isLoading: boolean = true;

  onBackPress(): boolean {
    if (this.controller.accessBackward()) {
      this.controller.backward();
      return true;
    }
    return false;
  }

  private saveImage(url: string): void {
    const ctx = getContext(this) as common.Context;
    const filePath = `${ctx.filesDir}/suxiaofu_${Date.now()}.jpg`;
    request.downloadFile(ctx, { url: url, filePath: filePath })
      .then((task: request.DownloadTask) => {
        task.on('complete', () => {
          try {
            const helper = photoAccessHelper.getPhotoAccessHelper(ctx);
            helper.createAsset(photoAccessHelper.PhotoType.IMAGE, 'jpg')
              .then((uri: string) => {
                const out = fileIo.openSync(uri, fileIo.OpenMode.WRITE_ONLY);
                const src = fileIo.openSync(filePath, fileIo.OpenMode.READ_ONLY);
                fileIo.copyFileSync(src.fd, out.fd);
                fileIo.closeSync(src);
                fileIo.closeSync(out);
                fileIo.unlinkSync(filePath);
                promptAction.showToast({ message: '已保存到相册' });
              })
              .catch((e: BusinessError) => {
                hilog.error(DOMAIN, TAG, 'createAsset fail %{public}s', e.message);
                promptAction.showToast({ message: '保存失败' });
              });
          } catch (e) {
            promptAction.showToast({ message: '保存失败' });
          }
        });
        task.on('fail', () => {
          promptAction.showToast({ message: '下载失败' });
        });
      })
      .catch(() => {
        promptAction.showToast({ message: '下载失败' });
      });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Progress({ value: 0, type: ProgressType.Linear })
          .width('100%').height(3).color('#317AF7')
      }
      Web({ src: TARGET_URL, controller: this.controller })
        .width('100%')
        .layoutWeight(1)
        .geolocationAccess(true)
        .javaScriptAccess(true)
        .domStorageAccess(true)
        .mixedMode(MixedMode.All)
        .cacheMode(CacheMode.Default)
        .onPageBegin(() => { this.isLoading = true; })
        .onPageEnd(() => { this.isLoading = false; })
        .onGeolocationShow((event: webview.GeolocationEvent) => {
          try {
            event.handle(true);
          } catch (e) {
            hilog.error(DOMAIN, TAG, 'geo handle fail');
          }
        })
        .onDownloadStart((event) => {
          hilog.info(DOMAIN, TAG, 'download %{public}s', event.url);
          this.saveImage(event.url);
        })
    }
    .width('100%')
    .height('100%')
  }
}

